<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useDemoStore} from '../stores/demo'
import {datasetProjects,datasetFormats,getDatasetVisualization,updateDatasetMetadata,datasetVideoUrl,formatBytes} from '../api/datasetUploads'
import type {DatasetVisualization,DatasetVideo} from '../api/datasetUploads'
const route=useRoute(),router=useRouter(),store=useDemoStore(),id=computed(()=>String(route.params.id))
const dataset=computed(()=>store.datasets.find(d=>d.id===id.value)),data=ref<DatasetVisualization|null>(null),loading=ref(true),error=ref(''),mediaError=ref(''),project=ref('未分类'),format=ref('LeRobot v2.1'),saving=ref(false),saved=ref('')
const selected=ref(0),query=ref(''),page=ref(0),rawPath=ref(''),rawMode=ref(false),playing=ref(false),time=ref(0),rate=ref(1),rawDuration=ref(0),fileQuery=ref('')
const players=new Map<string,HTMLVideoElement>();let generation=0
const episode=computed(()=>data.value?.episodes.find(e=>e.index===selected.value))
const matches=computed(()=>data.value?.episodes.filter(e=>`${e.index} ${e.tasks.join(' ')}`.toLowerCase().includes(query.value.toLowerCase()))??[])
const episodes=computed(()=>matches.value.slice(page.value*50,(page.value+1)*50))
const clips=computed<DatasetVideo[]>(()=>rawMode.value?(rawPath.value?[{camera:'原始视频',path:rawPath.value,start:0,end:rawDuration.value}]:[]):episode.value?.videos??[])
const duration=computed(()=>rawMode.value?rawDuration.value:(clips.value.length?Math.min(...clips.value.map(c=>c.end-c.start)):0))
const files=computed(()=>data.value?.files.filter(f=>f.path.toLowerCase().includes(fileQuery.value.toLowerCase())).slice(0,100)??[])
const fps=computed(()=>Number(data.value?.info?.fps)||30)
function stop(){playing.value=false;players.forEach(p=>p.pause())}
function seek(value:number){time.value=Math.max(0,Math.min(value,duration.value));clips.value.forEach(c=>{const p=players.get(c.camera);if(p&&p.readyState)p.currentTime=Math.min(c.start+time.value,c.end||p.duration)})}
function bind(camera:string,el:unknown){if(el instanceof HTMLVideoElement)players.set(camera,el);else players.delete(camera)}
function loaded(clip:DatasetVideo){const p=players.get(clip.camera);if(!p)return;if(rawMode.value)rawDuration.value=Number.isFinite(p.duration)?p.duration:0;p.currentTime=clip.start;p.playbackRate=rate.value}
async function play(){mediaError.value='';if(playing.value){stop();return}if(time.value>=duration.value-.05)seek(0);playing.value=true;try{await Promise.all(clips.value.map(c=>{const p=players.get(c.camera);if(!p)return;p.playbackRate=rate.value;return p.play()}))}catch{stop();mediaError.value='视频无法播放。请检查文件完整性及浏览器是否支持该编码。'}}
function tick(clip:DatasetVideo){const p=players.get(clip.camera);if(!p)return;if(p.currentTime>=clip.end&&clip.end>0)p.pause();if(clip.camera===clips.value[0]?.camera){time.value=Math.max(0,p.currentTime-clip.start);if(time.value>=duration.value-.04){stop();return}if(playing.value)clips.value.slice(1).forEach(c=>{const other=players.get(c.camera);if(other&&other.readyState&&Math.abs(other.currentTime-c.start-time.value)>.25)other.currentTime=Math.min(c.start+time.value,c.end)})}}
function choose(index:number){stop();if(index===selected.value)seek(0);selected.value=index;rawMode.value=false;time.value=0;mediaError.value=''}
watch([rawPath,rawMode],()=>{stop();time.value=0;rawDuration.value=0;mediaError.value=''})
watch(query,()=>page.value=0);watch(rate,()=>players.forEach(p=>p.playbackRate=rate.value))
async function load(){const current=++generation;stop();loading.value=true;error.value='';data.value=null;try{await store.syncUploadedDatasets();if(current!==generation)return;project.value=dataset.value?.project||'未分类';format.value=dataset.value?.format||'LeRobot v2.1';if(dataset.value?.source!=='upload')return;const result=await getDatasetVisualization(id.value);if(current!==generation)return;data.value=result;selected.value=result.episodes[0]?.index??0;rawMode.value=!result.episodes.length;rawPath.value=result.videos[0]?.path??'';const item=dataset.value;if(item&&Number.isSafeInteger(result.info?.total_episodes)){item.episodes=result.info!.total_episodes;store.persist()}}catch(e){if(current===generation)error.value=e instanceof Error?e.message:'读取失败。'}finally{if(current===generation)loading.value=false}}
async function save(){saving.value=true;saved.value='';try{if(dataset.value?.source==='upload')await updateDatasetMetadata(id.value,project.value,format.value);if(dataset.value){dataset.value.project=project.value;dataset.value.format=format.value;store.persist()}saved.value='分类已保存'}catch(e){error.value=e instanceof Error?e.message:'保存失败。'}finally{saving.value=false}}
onMounted(load);watch(id,load);onBeforeUnmount(()=>{generation++;stop()})
</script>
<template><div class="page-heading"><div><div class="eyebrow">ROBOTIC LAB / DATASET EXPLORER</div><h1>{{dataset?.name||'数据集可视化'}}<span class="heading-dot">.</span></h1><p>浏览任务片段、多相机画面与数据结构。</p></div><button class="button" @click="router.push('/datasets')">返回数据集</button></div><div v-if="error" class="form-error" role="alert">{{error}} <button class="text-link" @click="load">重试</button></div><div v-if="loading" class="empty-state">正在读取视频索引与元数据…</div><template v-else><div class="viewer-stats"><span>{{data?.version||dataset?.format||'未知格式'}}</span><span>{{data?.info?.total_episodes??'—'}} Episodes</span><span>{{data?.info?.total_frames??'—'}} 帧</span><span>{{data?.info?.fps??'—'}} FPS</span><span>{{data?.videos.length??0}} 个视频文件</span><span>{{dataset?.size}}</span></div><div v-if="dataset?.source!=='upload'" class="empty-state">{{dataset?'该条目为 Mock，没有真实视频。请导入实际数据集后预览。':'未找到数据集。'}}</div><div v-for="warning in data?.warnings" :key="warning" class="viewer-warning">{{warning}}</div><div class="explorer"><aside class="episode-panel"><div class="pane-title"><strong>Episodes</strong><span>{{matches.length}}</span></div><input v-model="query" placeholder="搜索编号或任务…" aria-label="搜索 Episode"/><div class="episode-list"><button v-for="e in episodes" :key="e.index" :class="{selected:!rawMode&&e.index===selected}" @click="choose(e.index)"><strong>Episode {{String(e.index).padStart(4,'0')}}</strong><small>{{e.length}} 帧 · {{e.videos.length}} 个视角</small><span>{{e.tasks.join(' / ')||'未提供任务描述'}}</span></button><p v-if="!episodes.length" class="muted">暂无可解析的 Episode。</p></div><div class="pager"><button class="button" :disabled="page===0" @click="page--">上一页</button><button class="button" :disabled="(page+1)*50>=matches.length" @click="page++">下一页</button></div></aside><main class="preview-panel"><div class="pane-title"><strong>{{rawMode?'原始视频预览':`Episode ${selected}`}}</strong><label><input v-model="rawMode" type="checkbox"/> 按视频文件浏览</label></div><select v-if="rawMode" v-model="rawPath" aria-label="选择视频文件"><option v-for="v in data?.videos" :key="v.path" :value="v.path">{{v.path}}</option></select><p v-if="rawMode" class="viewer-warning">原始文件可能包含多个 Episode，当前展示完整文件。</p><p v-else class="task-caption">{{episode?.tasks.join(' / ')||'该片段未提供任务描述'}}</p><div class="camera-grid"><div v-for="clip in clips" :key="`${selected}:${clip.path}:${clip.camera}:${rawMode}`" class="camera"><div class="camera-title"><span class="live-dot"></span>{{clip.camera}}</div><video :ref="el=>bind(clip.camera,el)" :src="datasetVideoUrl(id,clip.path)" preload="metadata" muted playsinline @loadedmetadata="loaded(clip)" @timeupdate="tick(clip)" @ended="stop" @error="mediaError='视频无法解码或文件不可用，请检查编码和上传完整性。'"/><small>{{rawMode?'完整文件':`${clip.start.toFixed(2)} – ${clip.end.toFixed(2)} s`}}</small></div></div><div v-if="!clips.length" class="video-empty">暂无可播放画面<br/><small>可尝试按视频文件浏览；图片内嵌型数据和压缩包暂不支持视频预览。</small></div><div v-if="mediaError" class="form-error" role="alert">{{mediaError}}</div><div class="transport"><input type="range" :value="time" min="0" :max="duration||1" :step="1/fps" :disabled="!clips.length" aria-label="视频时间轴" @input="seek(Number(($event.target as HTMLInputElement).value))"/><div><button class="button primary" :disabled="!clips.length" @click="play">{{playing?'暂停':'播放'}}</button><button class="button" :disabled="!clips.length" @click="stop();seek(time-1/fps)">上一帧</button><button class="button" :disabled="!clips.length" @click="stop();seek(time+1/fps)">下一帧</button><span>{{time.toFixed(2)}} / {{duration.toFixed(2)}} s</span><select v-model.number="rate" aria-label="播放速度"><option :value="0.5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option></select></div></div></main><aside class="metadata-panel"><h3>数据集信息</h3><label>所属项目<select v-model="project"><option v-for="p in datasetProjects" :key="p">{{p}}</option></select></label><label>格式标注<select v-model="format"><option v-if="!datasetFormats.includes(format)">{{format}}</option><option v-for="f in datasetFormats" :key="f">{{f}}</option></select></label><button class="button" :disabled="saving||!dataset" @click="save">{{saving?'保存中…':'保存分类'}}</button><small role="status">{{saved}}</small><dl><dt>机器人类型</dt><dd>{{data?.info?.robot_type||'未提供'}}</dd><dt>数据说明</dt><dd>{{dataset?.description||'暂无说明'}}</dd><dt>存储位置</dt><dd>{{dataset?.path}}</dd></dl><p class="muted">格式标注不转换文件；实际版本以 meta/info.json 为准。</p></aside></div><section class="dataset-details"><div class="panel"><div class="pane-title"><strong>数据字段 / Features</strong><span>{{data?.features.length??0}} 个字段</span></div><div v-for="f in data?.features" :key="f.key" class="feature-row"><code>{{f.key}}</code><span>{{f.dtype}} · {{f.shape?.join(' × ')}}</span></div><p v-if="!data?.features.length" class="empty-state">没有可解析的字段定义。</p></div><div class="panel"><div class="pane-title"><strong>文件目录</strong><span>{{data?.files.length??0}} 个文件</span></div><input v-model="fileQuery" placeholder="搜索文件路径…" aria-label="搜索文件"/><div class="file-list"><div v-for="f in files" :key="f.path"><code>{{f.path}}</code><span>{{formatBytes(f.size)}}</span></div></div><small class="muted">最多显示 100 条匹配文件。</small></div></section></template></template>
<style scoped>
.viewer-stats{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:22px}.viewer-stats span{border:1px solid var(--border);background:var(--surface);padding:9px 13px;border-radius:6px;font-size:12px}.viewer-warning{padding:9px 13px;background:#b88c1510;color:var(--muted);font-size:12px;line-height:1.7;margin-bottom:10px}.explorer{display:grid;grid-template-columns:210px minmax(0,1fr) 230px;border:1px solid var(--border);border-radius:12px;overflow:hidden;background:var(--surface)}.episode-panel,.metadata-panel{padding:18px;background:var(--subtle)}.episode-panel{border-right:1px solid var(--border)}.metadata-panel{border-left:1px solid var(--border)}.pane-title{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px;margin-bottom:18px}.pane-title span{font-size:11px;color:var(--muted)}.pane-title label{font-size:11px;display:flex;align-items:center;gap:6px}.pane-title input{width:auto}input:not([type=checkbox]):not([type=range]),select{width:100%;padding:9px 10px;border:1px solid var(--border);border-radius:6px;background:var(--surface);color:var(--text);font-size:12px}.episode-list{max-height:520px;overflow:auto;margin-top:14px}.episode-list button{display:flex;flex-direction:column;gap:7px;width:100%;padding:13px 10px;text-align:left;background:none;border:1px solid transparent;border-bottom-color:var(--border);color:var(--text);cursor:pointer;border-radius:6px}.episode-list button.selected{border-color:var(--blue);background:#367bf510}.episode-list strong{font-size:12px}.episode-list small,.episode-list span{font-size:10px;color:var(--muted);line-height:1.5}.pager{display:flex;gap:6px;margin-top:14px}.pager button{padding:7px;font-size:10px}.preview-panel{padding:20px;min-width:0}.task-caption{font-size:12px;color:var(--muted);margin-bottom:18px}.camera-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.camera{background:#101c30;border-radius:9px;overflow:hidden;color:#c9d8ed}.camera-title{display:flex;align-items:center;gap:7px;padding:12px;font-size:11px;overflow-wrap:anywhere}.live-dot{height:6px;width:6px;border-radius:50%;background:#53bcaa;flex-shrink:0}.camera video{display:block;width:100%;aspect-ratio:4/3;object-fit:contain;background:#08111f}.camera small{display:block;padding:8px 12px;font-size:10px;color:#91a6c3}.video-empty{background:#101c30;color:#a9bad1;text-align:center;line-height:2.2;padding:80px 20px;border-radius:8px;font-size:14px}.video-empty small{font-size:11px}.transport{margin-top:22px}.transport>input{width:100%;accent-color:var(--blue)}.transport>div{display:flex;align-items:center;gap:8px;margin-top:14px;flex-wrap:wrap}.transport span{font:11px monospace;margin-left:auto}.transport select{width:65px}.transport button{padding:8px 10px;font-size:11px}.metadata-panel h3{font-size:13px;margin-bottom:20px}.metadata-panel label{display:flex;flex-direction:column;gap:8px;font-size:11px;margin-bottom:15px}.metadata-panel small{display:block;color:#31a180;margin-top:8px}.metadata-panel dl{font-size:11px;line-height:1.8}.metadata-panel dt{color:var(--muted);margin-top:20px}.metadata-panel dd{margin:5px 0;overflow-wrap:anywhere}.metadata-panel p{font-size:10px;line-height:1.8;margin-top:20px}.dataset-details{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:22px}.dataset-details>.panel{padding:20px;min-width:0}.feature-row,.file-list>div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--border);padding:12px 0;font-size:11px}.feature-row code,.file-list code{overflow-wrap:anywhere;min-width:0}.feature-row span,.file-list span{color:var(--muted);flex-shrink:0}.file-list{max-height:260px;overflow:auto;margin:10px 0}button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:1200px){.explorer{grid-template-columns:180px minmax(0,1fr)}.metadata-panel{grid-column:1/-1;border-top:1px solid var(--border);border-left:0}}@media(max-width:750px){.explorer,.dataset-details{grid-template-columns:1fr}.episode-list{max-height:180px}.episode-panel{border-right:0;border-bottom:1px solid var(--border)}.camera-grid{grid-template-columns:1fr}.metadata-panel{grid-column:auto}}
</style>
